export function submitLead(payload) {
  return api.post('/leads', payload);
}

export function appendFollowup(leadId, content) {
  return api.post(`/leads/${leadId}/followups`, { content });
}

// 页面结构：列表页 + 详情抽屉
// 首版无历史模块需要兼容

export async function exportLeads(params) {
  return api.get('/leads/export', { params, responseType: 'blob' });
}

// reverted: mention notification side effects
export const mentionFeatureEnabled = false;

